    internal static string DescribeLiveFixture(string processState, string cyclesPath)
    {
        string cyclesLast = "<none>";
        var cyclesLines = 0;
        if (File.Exists(cyclesPath))
        {
            try
            {
                var lines = File.ReadAllLines(cyclesPath);
