    internal static async Task WaitUntilAsync(
        Func<bool> predicate,
        TimeSpan timeout,
        Func<string>? diagnostics = null,
        [CallerArgumentExpression(nameof(predicate))] string? description = null)
    {
        var stopwatch = Stopwatch.StartNew();
        Exception? lastError = null;
        var passes = 0;
        while (stopwatch.Elapsed < timeout)
        {
            passes++;
            try
            {
                if (predicate())
                {
                    return;
                }
            }
            catch (Exception exception)
            {
                lastError = exception;
            }

            await Task.Delay(50);
        }

        var diagnostic = $"{description}: timed out; elapsed_ms={stopwatch.ElapsedMilliseconds}; passes={passes}; last_error={lastError?.Message ?? "<none>"}; {diagnostics?.Invoke() ?? "<no fixture diagnostics>"}";
        Assert.Fail(diagnostic);
    }

    private static void WriteVerificationArtifact(string name, object payload)
    {
        var outputRoot = Environment.GetEnvironmentVariable(VerificationRootEnvironmentVariable);
        if (string.IsNullOrWhiteSpace(outputRoot))
        {
            return;
        }

        Directory.CreateDirectory(outputRoot);
        var finalPath = Path.Combine(outputRoot, $"{name}.json");
        var temporaryPath = Path.Combine(outputRoot, $".{name}.{Guid.NewGuid():N}.tmp");
        File.WriteAllText(temporaryPath, JsonSerializer.Serialize(payload, JsonOptions));
        File.Move(temporaryPath, finalPath, overwrite: true);
    }
}

